sys_variable_value.value:
(function execute(inputs, outputs) {
   var fieldMapping = {
       "v_valor_da_amortizacao_interna": "amortizacao_interna",
       "v_valor_da_amortizacao_externa": "amortizacao_externa",
       "v_juros_e_encargos_interna": "juros_interno",
       "v_juros_e_encargos_externa": "juros_externo",
       "v_ano": "ano"
   };


   var grMultiRow = new GlideRecord('sc_multi_row_question_answer');
   grMultiRow.addEncodedQuery('row_index=' + inputs.row_index + '^parent_id=' + inputs.parent_id);
   grMultiRow.query();

   while (grMultiRow.next()) {
       var questionName = grMultiRow.item_option_new.name;
       var value = grMultiRow.getValue('value');

       if (fieldMapping[questionName]) {
           fieldMapping[questionName] = value;
       }
   }

outputs.amortizacao_interna = fieldMapping['v_valor_da_amortizacao_interna'];
outputs.amortizacao_externa = fieldMapping['v_valor_da_amortizacao_externa'];
outputs.juros_interno = fieldMapping['v_juros_e_encargos_interna'];
outputs.juros_externo = fieldMapping['v_juros_e_encargos_externa'];
outputs.ano = fieldMapping['v_ano'];

})(inputs, outputs);

